-- Наполнение FAQ новыми вопросами по функциям, добавленным 27 июля:
-- колонка «На удержании» на доске задач и фильтрация задач по серверу в разделе «Патчи».
INSERT INTO faq_items (question, answer, sort_order) VALUES
('Что такое колонка «На удержании» и как ей пользоваться?', '<p>«На удержании» — отдельная колонка слева от To Do, куда можно временно отложить задачу любого статуса, не меняя сам статус деплоя. По умолчанию она свёрнута в узкую полосу с вертикальной надписью HOLD и счётчиком задач — нажмите на неё (или на стрелку), чтобы развернуть и увидеть карточки.</p>
<p>Перенести задачу на удержание можно перетаскиванием карточки на свёрнутую или развёрнутую колонку. Когда задачу нужно вернуть в работу, снимите её с удержания — при этом всегда нужно самостоятельно выбрать, в какую колонку она попадёт (To Do, In Progress или Done).</p>', 29),
('Приходят ли уведомления в Telegram по задачам на удержании?', '<p>Нет — пока задача находится «На удержании», назначение исполнителей и изменение статуса деплоя не отправляют сообщения в Telegram, чтобы не отвлекать команду по отложенным задачам. Внутреннее уведомление (колокольчик в приложении) при этом всё равно создаётся.</p>
<p>Комментарии к задаче на удержании уведомляют в Telegram как обычно — это правило не распространяется на переписку. Как только задачу переносят из «На удержании» в любую другую колонку, уведомления снова начинают приходить в Telegram в полном объёме.</p>', 30),
('Почему в разделе «Патчи» список задач меняется при переключении сервера?', '<p>В разделе «Патчи» выпадающий список «Без выбранной задачи» теперь показывает только задачи того сервера, вкладка которого выбрана (С4х1, HFx3 old или HF new) — это исключает путаницу, когда к файлам патча случайно привязывают задачу с другого сервера.</p>
<p>Если переключить вкладку сервера, а ранее выбранная задача относится к другому серверу, выбор в списке автоматически сбрасывается на «Без выбранной задачи».</p>', 31);
